local item_lib = require("items")
local phase = "ready"

function event_trade(e)
  local replacement = eq.get_entity_list():GetMobByNpcTypeID(116573)
  if phase == "ready" and not replacement.valid and item_lib.check_turn_in(e.trade, {item1 = 1459}) then
    phase = "pending"
    e.self:Say("You gotta be kiddin me, Avalanche Ale? Haven't had a bottle a this stuff in ages. Brell bless you, " .. e.other:GetCleanName() .. "! Glug, glug, glug...")
    eq.set_timer("drink", 53000)
  end
  item_lib.return_items(e.self, e.other, e.trade)
end

function event_timer(e)
  if e.timer == "drink" and phase == "pending" then
    phase = "poisoned"; eq.stop_timer("drink")
    -- Source DoAnim(15) has no rendered implementation yet. Keep its delay;
    -- a successful timer/loot test must not be reported as collapse-pose parity.
    eq.set_timer("transform", 5000)
  elseif e.timer == "transform" and phase == "poisoned" then
    phase = "ended"; eq.stop_timer("transform")
    e.self:Say("Uhhh... I'm not feeling so good. Someone call for a cleric.")
    -- Source explicitly returns to this authored point even if pulled away.
    eq.unique_spawn(116573, 0, 0, 2365, -61, 150, 119)
    eq.depop_with_timer()
  end
end
function event_death_complete(e)
  phase = "ended"; eq.stop_timer("drink"); eq.stop_timer("transform")
end
